source(file.path(Sys.getenv('BMONTH_FDIR'),'0.common.R'));source(file.path(Sys.getenv('BMONTH_FDIR'),'mediation.R'))
base<-load_cohort();B<-as.integer(Sys.getenv('BMONTH_MED_BOOT','100'));set.seed(12345)
scan_layer<-function(layer){mf<-file.path(indir,'Rdata',paste0(layer,'.rds'));om<-validate_ids(readRDS(mf),'eid',paste0(layer,'.rds'));features<-setdiff(names(om),'eid');features<-features[vapply(om[features],is.numeric,logical(1))];d0<-inner_join(base,om[,c('eid',features),drop=FALSE],by='eid');allres<-list();for(x in EXPOSURES){message('[med] ',layer,' / ',x,' X->M');xa<-bind_rows(lapply(features,function(m)screen_a(d0,x,m)));xa$FDR_a<-p.adjust(xa$p_a,'BH');cand_a<-xa$mediator[which(xa$FDR_a<.05)];write_csv2(xa,paste0('med_',layer,'_',x,'_Xa.csv'));for(y in OUTCOMES){d<-ensure_outcome(d0,y);xb<-if(length(cand_a))bind_rows(lapply(cand_a,function(m)screen_b(d,x,m,y)))else tibble(mediator=character(),N_b=integer(),b=double(),p_b=double());xb$FDR_b<-p.adjust(xb$p_b,'BH');write_csv2(xb,paste0('med_',layer,'_',x,'_',y,'_Mb.csv'));cands<-xb$mediator[which(xb$p_b<.05)];det<-if(length(cands))bind_rows(lapply(cands,function(m)mediate_feature(d,x,m,y,B)))else empty_mediation();det<-det%>%left_join(select(xa,mediator,a,p_a,FDR_a),by='mediator')%>%left_join(select(xb,mediator,b,p_b,FDR_b),by='mediator');det$layer<-rep(layer,nrow(det));det$FDR_indirect<-p.adjust(det$p_boot,'BH');allres[[paste(x,y)]]<-det}};bind_rows(allres)}
res<-bind_rows(scan_layer('prot'),scan_layer('met'));write_csv2(res,'mediation.csv');saveRDS(res,file.path(rawdir,'mediation.rds'))
writeLines(c('Exploratory associational mediation, not causal natural indirect effects.','Scalar cyclic components are analyzed separately; a full 2-df seasonal cycle has no single mediation coefficient.','Continuous exposures are standardized within each complete-case mediation sample; binary season contrasts remain 0/1.','X->M uses BH FDR<0.05; M->Y uses P<0.05 among selected candidates; bootstrap does not repeat feature selection.'),file.path(rawdir,'mediation_methods.txt'))
